 int nextTrack(){int n=songs.size(),i=p.getInt("index",0);if(n==0||p.getBoolean("stopAfter",false))return -1;if(p.getBoolean("shuffle",false)&&n>1)return p.getInt("nextIndex",-1);if(i+1<n)return i+1;return p.getBoolean("repeat",true)||p.getBoolean("nonstop",true)?0:-1;}void active(TextView v,boolean on){v.setBackground(bg(on?0xff176b68:0xff303746,on?0xff124d50:0xff222936,16));v.setTextColor(on?0xffb5fff2:0xffffffff);}void renderQueue(){if(queue==null)return;queue.removeAllViews();for(int j=0;j<songs.size();j++){final int k=j;String u=songs.get(j);LinearLayout row=new LinearLayout(this);queue.addView(row);int current=p.getInt("index",0),next=nextTrack();boolean now=j==current;row.setBackground(bg(now?0xff176b68:j==next?0xff34465a:0xff222936,0xff222936,10));TextView t=label((now?(p.getBoolean("playing",false)?"▶ กำลังเล่น • ":"เลือกอยู่ • "):j==next?"ถัดไป • ":"")+(u.startsWith("https://")?"YouTube • "+Uri.parse(u).getQueryParameter("v"):name(Uri.parse(u))),14);t.setMaxLines(2);row.addView(t,new LinearLayout.LayoutParams(0,dp(30),1));t.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("ลบออกจากเพลย์ลิสต์").setMessage("ไม่ลบไฟล์ต้นฉบับ").setPositiveButton("ลบ",(d,w)->{int current=p.getInt("index",0);if(k==current){send("PAUSE");}songs.remove(k);p.edit().putInt("index",Math.max(0,Math.min(songs.size()-1,current-(k<current?1:0)))).apply();save();if(k==current)send("RESET");}).setNegativeButton("ยกเลิก",null).show();return true;});t.setOnClickListener(v->{if(u.startsWith("https://")){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){}}else{Intent i=new Intent(this,PlayerService.class).setAction("SELECT").putExtra("index",k);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}});TextView up=label("↑",22),down=label("↓",22);row.addView(up,new LinearLayout.LayoutParams(dp(36),dp(44)));row.addView(down,new LinearLayout.LayoutParams(dp(36),dp(44)));up.setOnClickListener(v->move(k,-1));down.setOnClickListener(v->move(k,1));}}void move(int k,int d){int n=k+d;if(n<0||n>=songs.size())return;int i=p.getInt("index",0);Collections.swap(songs,k,n);p.edit().putInt("index",i==k?n:i==n?k:i).apply();save();}void buildPlayer(){boolean wide=getResources().getConfiguration().orientation==2;player=new LinearLayout(this);player.setOrientation(wide?0:1);player.setPadding(dp(12),dp(8),dp(12),dp(8));shell.addView(player,new LinearLayout.LayoutParams(-1,0,1));cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setBackground(bg(0xff45576e,0xff161b28,24));cover.setImageResource(com.kai.automusic.R.drawable.autoplay_icon);cover.setClipToOutline(true);player.addView(cover,new LinearLayout.LayoutParams(dp(64),dp(64)));LinearLayout controls=new LinearLayout(this);controls.setOrientation(1);controls.setGravity(16);controls.setPadding(dp(14),dp(4),dp(14),dp(4));player.addView(controls,wide?new LinearLayout.LayoutParams(0,-1,1.5f):new LinearLayout.LayoutParams(-1,0,1));track=label("ยังไม่ได้เลือกเพลง",16);track.setMaxLines(2);controls.addView(track);artist=label("เพลงในเครื่อง",14);controls.addView(artist);progress=new SeekBar(this);controls.addView(progress);progress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){}public void onStartTrackingTouch(SeekBar s){dragging=true;}public void onStopTrackingTouch(SeekBar s){dragging=false;Intent i=new Intent(MainActivity.this,PlayerService.class).setAction("SEEK").putExtra("ms",s.getProgress());startService(i);}});clock=label("0:00 / 0:00",12);controls.addView(clock);nextLabel=label("",12);controls.addView(nextLabel);LinearLayout row=new LinearLayout(this);controls.addView(row);action(row,"⏮",()->send("PREV")).setContentDescription("เพลงก่อนหน้า");playButton=action(row,"▶",()->send(p.getBoolean("playing",false)?"PAUSE":"PLAY"));action(row,"⏭",()->send("NEXT")).setContentDescription("เพลงถัดไป");LinearLayout extra=new LinearLayout(this);controls.addView(extra);shuffleButton=action(extra,"⇄ สุ่ม",()->{if(songs.size()>1){int i=Math.max(0,Math.min(songs.size()-1,p.getInt("index",0)));String current=songs.remove(i);Collections.shuffle(songs);songs.add(0,current);p.edit().putInt("index",0).putBoolean("shuffle",false).putBoolean("shuffledOrder",true).apply();save();}});repeatButton=action(extra,"↻ เล่นวน",()->p.edit().putBoolean("repeat",!p.getBoolean("repeat",true)).apply());SeekBar volume=new SeekBar(this);android.media.AudioManager am=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);volume.setMax(am.getStreamMaxVolume(3));volume.setProgress(am.getStreamVolume(3));controls.addView(label("ระดับเสียง",12));controls.addView(volume);Switch nonstop=new Switch(this);nonstop.setText("เล่นเพลงไม่หยุด");nonstop.setChecked(p.getBoolean("nonstop",true));controls.addView(nonstop);nonstop.setOnCheckedChangeListener((v,b)->p.edit().putBoolean("nonstop",b).apply());Switch end=new Switch(this);end.setText("หยุดเมื่อเพลงนี้จบ");end.setChecked(p.getBoolean("stopAfter",false));controls.addView(end);end.setOnCheckedChangeListener((v,b)->p.edit().putBoolean("stopAfter",b).apply());p.registerOnSharedPreferenceChangeListener(endListener=(prefs,key)->{if("stopAfter".equals(key))end.setChecked(prefs.getBoolean(key,false));});LinearLayout qhead=new LinearLayout(this);controls.addView(qhead);TextView qt=label("เพลย์ลิสต์",14);qhead.addView(qt,new LinearLayout.LayoutParams(0,-2,1));TextView plus=label("＋",24);qhead.addView(plus);plus.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("เพิ่มเพลง").setItems(new String[]{"ไฟล์เพลง","โฟลเดอร์","ลิงก์ YouTube"},(d,w)->{if(w==0){Intent f=new Intent(Intent.ACTION_OPEN_DOCUMENT);f.setType("*/*");f.addCategory(Intent.CATEGORY_OPENABLE);f.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(f,1);}else if(w==1)startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE),2);else{EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("ลิงก์ YouTube").setView(e).setPositiveButton("เพิ่ม",(x,y)->{String link=e.getText().toString().trim();Uri u=Uri.parse(link);String h=u.getHost();if("https".equals(u.getScheme())&&h!=null&&(h.equals("youtu.be")||h.equals("youtube.com")||h.endsWith(".youtube.com"))&&!songs.contains(link)){songs.add(link);save();}}).setNegativeButton("ยกเลิก",null).show();}}).show());ScrollView qs=new ScrollView(this);queue=new LinearLayout(this);queue.setOrientation(1);qs.addView(queue);controls.addView(qs,new LinearLayout.LayoutParams(-1,0,1));renderQueue();volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){if(user)am.setStreamVolume(3,n,0);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});}
 String time(int ms){return String.format(java.util.Locale.US,"%d:%02d",ms/60000,(ms/1000)%60);}
 Runnable tick=new Runnable(){public void run(){int i=p.getInt("index",0);if(i!=shown&&i>=0&&i<songs.size()){shown=i;Uri u=Uri.parse(songs.get(i));track.setText(name(u));artist.setText("เพลงในเครื่อง");cover.setImageResource(com.kai.automusic.R.drawable.autoplay_icon);try{android.media.MediaMetadataRetriever m=new android.media.MediaMetadataRetriever();try{m.setDataSource(MainActivity.this,u);String t=m.extractMetadata(7),a=m.extractMetadata(2);if(t!=null)track.setText(t);if(a!=null)artist.setText(a);byte[] bytes=m.getEmbeddedPicture();if(bytes!=null){android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inSampleSize=2;android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(bitmap!=null){cover.setImageBitmap(bitmap);int color=bitmap.getPixel(bitmap.getWidth()/2,bitmap.getHeight()/2);shell.setBackground(bg(color,0xff10141d,0));}}}finally{m.release();}}catch(Exception e){}}boolean playing=p.getBoolean("playing",false),shuffle=p.getBoolean("shuffle",false),repeat=p.getBoolean("repeat",true);playButton.setText(playing?"Ⅱ":"▶");playButton.setContentDescription(playing?"พักเพลง":"เล่นเพลง");active(playButton,playing);active(shuffleButton,shuffle||p.getBoolean("shuffledOrder",false));active(repeatButton,repeat);int next=nextTrack();nextLabel.setText(p.getBoolean("stopAfter",false)?"จะหยุดเมื่อเพลงนี้จบ":next>=0&&next<songs.size()?"ถัดไป: "+name(Uri.parse(songs.get(next))):"ไม่มีเพลงถัดไป");String state=i+":"+next+":"+playing;if(!state.equals(queueState)){queueState=state;renderQueue();}int pos=p.getInt("position",0),dur=p.getInt("duration",0);if(!dragging){progress.setMax(Math.max(1,dur));progress.setProgress(pos);}clock.setText(time(pos)+" / "+time(dur));ui.postDelayed(this,500);}};
 protected void onDestroy(){if(endListener!=null)p.unregisterOnSharedPreferenceChangeListener(endListener);super.onDestroy();}protected void onResume(){super.onResume();ui.removeCallbacks(tick);ui.post(tick);}protected void onPause(){ui.removeCallbacks(tick);super.onPause();}
 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("music",0);try{JSONArray a=new JSONArray(p.getString("songs","[]"));for(int i=0;i<a.length();i++)songs.add(a.getString(i));}catch(Exception e){} ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,24,24,24);s.addView(root);shell=new LinearLayout(this);shell.setOrientation(1);shell.setBackground(bg(0xff303b50,0xff10141d,0));setContentView(shell);LinearLayout nav=new LinearLayout(this);shell.addView(nav);action(nav,"กำลังเล่น",()->showPage(false));action(nav,"เพลย์ลิสต์ / ตั้งค่า",()->showPage(true));buildPlayer();settings=new LinearLayout(this);settings.setOrientation(1);settings.addView(s,new LinearLayout.LayoutParams(-1,-1));shell.addView(settings,new LinearLayout.LayoutParams(-1,0,1));showPage(p.getBoolean("setupPage",false));TextView title=new TextView(this);title.setText("Kaisoundgood AutoPlay • v1.7");title.setTextSize(26);root.addView(title);button("+ เพิ่มไฟล์เพลง",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,1);});button("+ เพิ่มโฟลเดอร์และโฟลเดอร์ย่อย",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE),2));toggle("เล่นเพลงเมื่อเสียบชาร์จ","auto",true);toggle("หยุดเพลงเมื่อถอดชาร์จ","unplug",true);toggle("สุ่มเพลง","shuffle",false);toggle("เล่นวนเพลย์ลิสต์","repeat",true);toggle("เริ่มระบบหลังเปิดเครื่อง","boot",true);toggle("เล่นเพลงหลังเปิดเครื่องแม้ไม่ได้ชาร์จ","bootPlay",true);toggle("พยายามเปิดหน้าแอปอัตโนมัติ","launch",true);toggle("เล่นต่อจากตำแหน่งล่าสุด","resume",true);button("บันทึกเพลย์ลิสต์",()->playlist(true));button("โหลดเพลย์ลิสต์",()->playlist(false));button("บันทึกลิงก์ YouTube / YouTube Music",()->{EditText e=new EditText(this);e.setText(p.getString("youtube",""));new AlertDialog.Builder(this).setTitle("ลิงก์เพลย์ลิสต์").setView(e).setPositiveButton("บันทึก",(d,w)->{String link=e.getText().toString().trim();Uri u=Uri.parse(link);String h=u.getHost();if("https".equals(u.getScheme())&&h!=null&&(h.equals("youtu.be")||h.equals("youtube.com")||h.endsWith(".youtube.com"))){p.edit().putString("youtube",link).apply();if(!songs.contains(link))songs.add(link);save();}else Toast.makeText(this,"ลิงก์ไม่ถูกต้อง",Toast.LENGTH_SHORT).show();}).setNegativeButton("ยกเลิก",null).show();});button("เปิดเพลย์ลิสต์ใน YouTube",()->{try{Uri u=Uri.parse(p.getString("youtube",""));if(!"https".equals(u.getScheme())||u.getHost()==null||!(u.getHost().equals("youtube.com")||u.getHost().endsWith(".youtube.com")||u.getHost().equals("youtu.be")))throw new Exception();startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(this,"กรุณาบันทึกลิงก์ YouTube ที่ถูกต้อง",Toast.LENGTH_LONG).show();}});button("เปิดระบบอัตโนมัติ",()->send("ARM"));button("เล่นเพลง",()->send("PLAY"));button("หยุดชั่วคราว",()->send("PAUSE"));button("เพลงถัดไป",()->send("NEXT"));button("ปิดระบบอัตโนมัติ",()->{p.edit().putBoolean("armed",false).apply();stopService(new Intent(this,PlayerService.class));});button("ล้างเพลย์ลิสต์",()->{songs.clear();save();send("PAUSE");});list=new TextView(this);root.addView(list);refresh();s.post(()->s.scrollTo(0,p.getInt("scroll",0)));s.setOnScrollChangeListener((v,x,y,ox,oy)->p.edit().putInt("scroll",y).apply());}
 void playlist(boolean saveMode){if(saveMode){EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("ชื่อเพลย์ลิสต์").setView(e).setPositiveButton("บันทึก",(d,w)->{String n=e.getText().toString().trim();if(!n.isEmpty())getSharedPreferences("playlists",0).edit().putString(n,new JSONArray(songs).toString()).apply();}).setNegativeButton("ยกเลิก",null).show();}else{android.content.SharedPreferences q=getSharedPreferences("playlists",0);String[] names=q.getAll().keySet().toArray(new String[0]);new AlertDialog.Builder(this).setTitle("เลือกเพลย์ลิสต์").setItems(names,(d,w)->{stopService(new Intent(this,PlayerService.class));songs.clear();try{JSONArray a=new JSONArray(q.getString(names[w],"[]"));for(int i=0;i<a.length();i++)songs.add(a.getString(i));}catch(Exception e){}p.edit().putInt("index",0).putInt("position",0).apply();save();send("ARM");}).show();}}
 void button(String t,Runnable r){Button b=new Button(this);b.setText(t);b.setAllCaps(false);b.setBackground(bg(0xff303746,0xff222936,12));b.setTextColor(-1);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.setMargins(0,dp(3),0,dp(3));root.addView(b,bp);b.setOnClickListener(v->r.run());}void toggle(String t,String k,boolean d){Switch s=new Switch(this);s.setChecked(p.getBoolean(k,d));s.setText(t+(s.isChecked()?" • เปิด":" • ปิด"));s.setTextColor(s.isChecked()?0xff80cbc4:0xffcccccc);root.addView(s);s.setOnCheckedChangeListener((v,c)->{p.edit().putBoolean(k,c).apply();s.setText(t+(c?" • เปิด":" • ปิด"));s.setTextColor(c?0xff80cbc4:0xffcccccc);});}
 void send(String a){Intent i=new Intent(this,PlayerService.class).setAction(a);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
 String name(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{"_display_name"},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception e){}return u.toString();}
 void add(Uri u,String n){if(n.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|mp4|wav|wave|flac|m4a|aac|ogg|opus|3gp|mkv|webm|amr)$")&&!songs.contains(u.toString()))songs.add(u.toString());}
 void walk(Uri tree,String id){Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);try(Cursor c=getContentResolver().query(children,new String[]{"document_id","_display_name","mime_type"},null,null,null)){while(c!=null&&c.moveToNext()){String child=c.getString(0);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2)))walk(tree,child);else add(DocumentsContract.buildDocumentUriUsingTree(tree,child),c.getString(1));}}}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null)return;try{if(r==2){Uri u=data.getData();getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);walk(u,DocumentsContract.getTreeDocumentId(u));}else if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)pick(data.getClipData().getItemAt(i).getUri());}else pick(data.getData());save();}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}
 void pick(Uri u){getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);add(u,name(u));}void save(){p.edit().putString("songs",new JSONArray(songs).toString()).apply();refresh();}void refresh(){shown=-1;renderQueue();StringBuilder b=new StringBuilder("เพลย์ลิสต์: "+songs.size()+" files\n");for(String u:songs)b.append(name(Uri.parse(u))).append('\n');list.setText(b);}
